eg_2305" s="T129.TIE3.2" e="T130">ridiculous</ts><nts n="HIAT:ip" id="Seg_2306">.</nts><nts n="HIAT:ip" id="Seg_2307"><![CDATA[ ]]></nts></ts><ts n="HIAT:u" id="Seg_2309" s="T130" e="T133"><ts n="HIAT:w" id="Seg_2311" s="T130" e="T130.TIE3.1">and</ts><nts n="HIAT:ip" id="Seg_2312"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2314" s="T130.TIE3.1" e="T131">eh</ts><nts n="HIAT:ip" id="Seg_2315"><![CDATA[ ]]></nts><ats n="HIAT:non-pho" id="Seg_2316" s="T131" e="T131.TIE3.1">•</ats><nts n="HIAT:ip" id="Seg_2317"><![CDATA[ ]]></nts><ats n="HIAT:non-pho" id="Seg_2318" s="T131.TIE3.1" e="T131.TIE3.2">•</ats><nts n="HIAT:ip" id="Seg_2319"><![CDATA[ ]]></nts><ats n="HIAT:non-pho" id="Seg_2320" s="T131.TIE3.2" e="T132">•</ats><nts n="HIAT:ip" id="Seg_2321"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2323" s="T132" e="T132.TIE3.1">You</ts><nts n="HIAT:ip" id="Seg_2324"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2326" s="T132.TIE3.1" e="T132.TIE3.2">know</ts><nts n="HIAT:ip" id="Seg_2327"><![CDATA[ ]]></nts><nts n="HIAT:ip" id="Seg_2328">(</nts><ts n="HIAT:w" id="Seg_2330" s="T132.TIE3.2" e="T132.TIE3.3">when</ts><nts n="HIAT:ip" id="Seg_2331">)</nts><nts n="HIAT:ip" id="Seg_2332"><![CDATA[ ]]></nts><nts n="HIAT:ip" id="Seg_2333">(</nts><nts n="HIAT:ip" id="Seg_2334">(</nts><ats n="HIAT:non-pho" id="Seg_2335" s="T132.TIE3.3" e="T133">inc.</ats><nts n="HIAT:ip" id="Seg_2336">)</nts><nts n="HIAT:ip" id="Seg_2337">)</nts><nts n="HIAT:ip" id="Seg_2338"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE3"><ts n="sc" id="Seg_2339" s="T10" e="T37"><ts n="e" id="Seg_2341" s="T10" e="T11">• • • </ts><ts n="e" id="Seg_2343" s="T11" e="T12">Ehm˙ </ts><ts n="e" id="Seg_2345" s="T12" e="T13">• • </ts><ts n="e" id="Seg_2347" s="T13" e="T14">I didn't/ didn't have any ambitions. </ts><ts n="e" id="Seg_2349" s="T14" e="T15">((breathes in)) </ts><ts n="e" id="Seg_2351" s="T15" e="T16">Eh, the/ there was nothing I particularly wanted to be really. </ts><ts n="e" id="Seg_2353" s="T16" e="T17">((breathes in)) </ts><ts n="e" id="Seg_2355" s="T17" e="T18">Cause I was at school. </ts><ts n="e" id="Seg_2357" s="T18" e="T19">• • • </ts><ts n="e" id="Seg_2359" s="T19" e="T20">For a bit. </ts><ts n="e" id="Seg_2361" s="T20" e="T21">((breathes in)) </ts><ts n="e" id="Seg_2363" s="T21" e="T22">(Until)/ til I was eighteen. </ts><ts n="e" id="Seg_2365" s="T22" e="T23">• • </ts><ts n="e" id="Seg_2367" s="T23" e="T24">And, eh </ts><ts n="e" id="Seg_2369" s="T24" e="T25">((1,5s)) </ts><ts n="e" id="Seg_2371" s="T25" e="T26">then I just </ts><ts n="e" id="Seg_2373" s="T26" e="T27">left </ts><ts n="e" id="Seg_2375" s="T27" e="T28">school and I still didn't have any ambition, </ts><ts n="e" id="Seg_2377" s="T28" e="T29">or any idea what I was gonna be. </ts><ts n="e" id="Seg_2379" s="T29" e="T30">((breathes in)) </ts><ts n="e" id="Seg_2381" s="T30" e="T31">Eh, we went into the group. </ts><ts n="e" id="Seg_2383" s="T31" e="T32">((breathes in)) </ts><ts n="e" id="Seg_2385" s="T32" e="T33">Eh, you know, I went into the group and ehm we played around for a bit. </ts><ts n="e" id="Seg_2387" s="T33" e="T34">((breathes in)) </ts><ts n="e" id="Seg_2389" s="T34" e="T35">And, only after a bit • eh must 've realised that this was the only ambition I'd really ever had. </ts><ts n="e" id="Seg_2391" s="T35" e="T36">• • • </ts><ts n="e" id="Seg_2393" s="T36" e="T37">Nothing else. </ts></ts><ts n="sc" id="Seg_2394" s="T40" e="T56"><ts n="e" id="Seg_2396" s="T40" e="T41">((1s)) </ts><ts n="e" id="Seg_2398" s="T41" e="T42">(Me) I don't know really ((laughs)) ehm˙ </ts><ts n="e" id="Seg_2400" s="T42" e="T43">• • • </ts><ts n="e" id="Seg_2402" s="T43" e="T44">I just wanna be able to do what I want to do. </ts><ts n="e" id="Seg_2404" s="T44" e="T45">• • </ts><ts n="e" id="Seg_2406" s="T45" e="T46">And so, you know, at/ • • at this moment this is what I want to do. </ts><ts n="e" id="Seg_2408" s="T46" e="T47">• • • </ts><ts n="e" id="Seg_2410" s="T47" e="T48">I may/ I may change later. </ts><ts n="e" id="Seg_2412" s="T48" e="T49">I may just get fed up and not wanna do that, </ts><ts n="e" id="Seg_2414" s="T49" e="T50">maybe wanna do something else. </ts><ts n="e" id="Seg_2416" s="T50" e="T51">((breathes in)) </ts><ts n="e" id="Seg_2418" s="T51" e="T52">Completely. </ts><ts n="e" id="Seg_2420" s="T52" e="T53">• • </ts><ts n="e" id="Seg_2422" s="T53" e="T54">But, ehm • • you know I should be able to do whatever I want to do. </ts><ts n="e" id="Seg_2424" s="T54" e="T55">• • • </ts><ts n="e" id="Seg_2426" s="T55" e="T56">Later on, ye know. </ts></ts><ts n="sc" id="Seg_2427" s="T72" e="T77"><ts n="e" id="Seg_2429" s="T72" e="T73">((1,2s)) </ts><ts n="e" id="Seg_2431" s="T73" e="T74">Eeh group. </ts><ts n="e" id="Seg_2433" s="T74" e="T75">((laughs)) </ts><ts n="e" id="Seg_2435" s="T75" e="T76">Well, I think </ts><ts n="e" id="Seg_2437" s="T76" e="T77">eh… </ts></ts><ts n="sc" id="Seg_2438" s="T79" e="T94"><ts n="e" id="Seg_2440" s="T79" e="T80">• No, I can't/ I can't get one in there. </ts><ts n="e" id="Seg_2442" s="T80" e="T81">((breathes in)) </ts><ts n="e" id="Seg_2444" s="T81" e="T82">I think ehm </ts><ts n="e" id="Seg_2446" s="T82" e="T83">((1,4s)) </ts><ts n="e" id="Seg_2448" s="T83" e="T84">the Animals • favourite group really. </ts><ts n="e" id="Seg_2450" s="T84" e="T85">((breathes in)) </ts><ts n="e" id="Seg_2452" s="T85" e="T86">(Only they)/ they're quite recent compared to a lot of the groups. </ts><ts n="e" id="Seg_2454" s="T86" e="T87">((breathes in)) </ts><ts n="e" id="Seg_2456" s="T87" e="T88">I mean they've been going long, </ts><ts n="e" id="Seg_2458" s="T88" e="T89">but they've only • come to the forefront recently. </ts><ts n="e" id="Seg_2460" s="T89" e="T90">((breathes in)) </ts><ts n="e" id="Seg_2462" s="T90" e="T91">Animals, the Searchers, the Rolling Stones. </ts><ts n="e" id="Seg_2464" s="T91" e="T92">• • • </ts><ts n="e" id="Seg_2466" s="T92" e="T93">Ehm˙ </ts><ts n="e" id="Seg_2468" s="T93" e="T94">• a lot, you know. </ts></ts><ts n="sc" id="Seg_2469" s="T109" e="T133"><ts n="e" id="Seg_2471" s="T109" e="T110">• • • </ts><ts n="e" id="Seg_2473" s="T110" e="T111">Well it bothers us if they're gonna get hurt, you know. </ts><ts n="e" id="Seg_2475" s="T111" e="T112">((breathes in)) </ts><ts n="e" id="Seg_2477" s="T112" e="T113">Cause actually some of them do ridiculous things, (ye know). </ts><ts n="e" id="Seg_2479" s="T113" e="T114">((breathes in)) </ts><ts n="e" id="Seg_2481" s="T114" e="T115">There was a fellow, </ts><ts n="e" id="Seg_2483" s="T115" e="T116">he wa/ he wasn't so much a fan, </ts><ts n="e" id="Seg_2485" s="T116" e="T117">he was a/ a fellow from Liverpool. </ts><ts n="e" id="Seg_2487" s="T117" e="T118">This was whi/ (whilst) we were in Australia. </ts><ts n="e" id="Seg_2489" s="T118" e="T119">We were in Sydney and we were on about </ts><ts n="e" id="Seg_2491" s="T119" e="T120">thee </ts><ts n="e" id="Seg_2493" s="T120" e="T121">eh • twelfth floor. </ts><ts n="e" id="Seg_2495" s="T121" e="T122">• ((breathes in)) </ts><ts n="e" id="Seg_2497" s="T122" e="T123">And he climbed right up the side of the building, </ts><ts n="e" id="Seg_2499" s="T123" e="T124">from balcony to balcony. </ts><ts n="e" id="Seg_2501" s="T124" e="T125">Twelve floors. </ts><ts n="e" id="Seg_2503" s="T125" e="T126">God! </ts><ts n="e" id="Seg_2505" s="T126" e="T127">((breathes in)) </ts><ts n="e" id="Seg_2507" s="T127" e="T128">You know, I mean, he could have just fallen off any second. </ts><ts n="e" id="Seg_2509" s="T128" e="T129">((breathes in)) </ts><ts n="e" id="Seg_2511" s="T129" e="T130">It was ridiculous. </ts><ts n="e" id="Seg_2513" s="T130" e="T131">and eh </ts><ts n="e" id="Seg_2515" s="T131" e="T132">• • • </ts><ts n="e" id="Seg_2517" s="T132" e="T133">You know (when) ((inc.)) </ts></ts></segmentation><annotation name="akz" tierref="TIE4"><ta id="Seg_2518" s="T26" e="T27">—</ta></annotation><annotation name="de" tierref="TIE5"><ta id="Seg_2519" s="T10" e="T11">• • • </ta><ta id="Seg_2520" s="T11" e="T12">Ähm˙ </ta><ta id="Seg_2521" s="T12" e="T13">• • </ta><ta id="Seg_2522" s="T13" e="T14">Ich hatte nicht/ hatte nicht viele Ambitionen. </ta><ta id="Seg_2523" s="T14" e="T15">((atmet ein)) </ta><ta id="Seg_2524" s="T15" e="T16">Ich wollte eigentlich nichts Spezielles wirklich werden. </ta><ta id="Seg_2525" s="T16" e="T17">((atmet ein)) </ta><ta id="Seg_2526" s="T17" e="T18">Weil ich in der Schule war. </ta><ta id="Seg_2527" s="T18" e="T19">• • • </ta><ta id="Seg_2528" s="T19" e="T20">Eine Zeit lang. </ta><ta id="Seg_2529" s="T20" e="T21">((atmet ein)) </ta><ta id="Seg_2530" s="T21" e="T22">Bis ich achtzehn war. </ta><ta id="Seg_2531" s="T22" e="T23">• • </ta><ta id="Seg_2532" s="T23" e="T24">Und äh </ta><ta id="Seg_2533" s="T24" e="T25">((1,5s)) </ta><ta id="Seg_2534" s="T25" e="T28">dann bin ich einfach von der Schule gegangen und ich hatte immer noch keine Ambition </ta><ta id="Seg_2535" s="T28" e="T29">oder irgendeine Ahnung, was ich werden wollte. </ta><ta id="Seg_2536" s="T29" e="T30">((atmet ein )) </ta><ta id="Seg_2537" s="T30" e="T31">Wir gründeten die Gruppe. </ta><ta id="Seg_2538" s="T31" e="T32">((atmet ein)) </ta><ta id="Seg_2539" s="T32" e="T33">Äh, du weißt, ich fing also bei der Gruppe an und wir spielten ein bisschen herum. </ta><ta id="Seg_2540" s="T33" e="T34">((atmet ein)) </ta><ta id="Seg_2541" s="T34" e="T35">Und nach einer Weile • ist mir wohl aufgefallen, dass das die einzige Ambition war, die ich je wirklich hatte. </ta><ta id="Seg_2542" s="T35" e="T36">• • • </ta><ta id="Seg_2543" s="T36" e="T37">Sonst nichts. </ta><ta id="Seg_2544" s="T40" e="T41">((1s)) </ta><ta id="Seg_2545" s="T41" e="T42">Ich weiß es nicht so genau ((lacht)) ähm˙ </ta><ta id="Seg_2546" s="T42" e="T43">• • • </ta><ta id="Seg_2547" s="T43" e="T44">Ich möchte einfach das machen können, wozu ich Lust habe. </ta><ta id="Seg_2548" s="T44" e="T45">• • </ta><ta id="Seg_2549" s="T45" e="T46">Also weißt du in/ in diesem Moment, ist es das, was ich machen möchte. </ta><ta id="Seg_2550" s="T46" e="T47">• • • </ta><ta id="Seg_2551" s="T47" e="T48">Es könnte/ könnte sich später ändern. </ta><ta id="Seg_2552" s="T48" e="T49">Ich könnte irgendwann davon genug haben und das nicht mehr machen wollen, </ta><ta id="Seg_2553" s="T49" e="T50">will vielleicht was anderes machen. </ta><ta id="Seg_2554" s="T50" e="T51">((atmet ein)) </ta><ta id="Seg_2555" s="T51" e="T52">Total. </ta><ta id="Seg_2556" s="T52" e="T53">• • </ta><ta id="Seg_2557" s="T53" e="T54">Aber ähm • • ich sollte immer in der Lage sein, das zu tun, worauf ich Lust habe. </ta><ta id="Seg_2558" s="T54" e="T55">• • • </ta><ta id="Seg_2559" s="T55" e="T56">Später, weißt du. </ta><ta id="Seg_2560" s="T72" e="T73">((1,2s)) </ta><ta id="Seg_2561" s="T73" e="T74">Ääh Gruppe. </ta><ta id="Seg_2562" s="T74" e="T75">((lacht)) </ta><ta id="Seg_2563" s="T75" e="T76">Also ich glaube </ta><ta id="Seg_2564" s="T76" e="T77">äh… </ta><ta id="Seg_2565" s="T79" e="T80">• Nein, da hab ich/ hab ich keine Chance. </ta><ta id="Seg_2566" s="T80" e="T81">((atmet ein)) </ta><ta id="Seg_2567" s="T81" e="T82">Ich glaube ähm </ta><ta id="Seg_2568" s="T82" e="T83">((1,4s)) </ta><ta id="Seg_2569" s="T83" e="T84">die Animals • Lieblingsgruppe wirklich. </ta><ta id="Seg_2570" s="T84" e="T85">((atmet ein)) </ta><ta id="Seg_2571" s="T85" e="T86">(Bloß sind sie)/ sind sie relativ neu im Vergleich zu vielen anderen Gruppen. </ta><ta id="Seg_2572" s="T86" e="T87">((atmet ein)) </ta><ta id="Seg_2573" s="T87" e="T88">Ich meine es gibt sie schon lange, </ta><ta id="Seg_2574" s="T88" e="T89">aber sie sind erst kürzlich groß rausgekommen. </ta><ta id="Seg_2575" s="T89" e="T90">((atmet ein)) </ta><ta id="Seg_2576" s="T90" e="T91">Animals, die Searchers, die Rolling Stones. </ta><ta id="Seg_2577" s="T91" e="T92">• • • </ta><ta id="Seg_2578" s="T92" e="T93">Ähm˙ </ta><ta id="Seg_2579" s="T93" e="T94">• eine Menge, du weißt schon. </ta><ta id="Seg_2580" s="T109" e="T110">• • • </ta><ta id="Seg_2581" s="T110" e="T111">Also wir machen uns Sorgen, wenn sie sich weh tun, weißt du. </ta><ta id="Seg_2582" s="T111" e="T112">((atmet ein)) </ta><ta id="Seg_2583" s="T112" e="T113">Denn manche machen wirklich bekloppte Sachen, (weißt du). </ta><ta id="Seg_2584" s="T113" e="T114">((atmet ein)) </ta><ta id="Seg_2585" s="T114" e="T115">Einmal gab es einen Typen, </ta><ta id="Seg_2586" s="T115" e="T116">er wa/ war nicht so sehr ein Fan, </ta><ta id="Seg_2587" s="T116" e="T117">er war ein Typ aus Liverpool. </ta><ta id="Seg_2588" s="T117" e="T118">Das war währ/ (während) wir in Australien waren. </ta><ta id="Seg_2589" s="T118" e="T121">Wir waren in Sydney und wir waren ungefähr im äh zwölften Stock. </ta><ta id="Seg_2590" s="T121" e="T122">• ((atmet ein)) </ta><ta id="Seg_2591" s="T122" e="T123">Und er kletterte einfach an der Seite des Gebäudes hoch, </ta><ta id="Seg_2592" s="T123" e="T124">von Balkon zu Balkon. </ta><ta id="Seg_2593" s="T124" e="T125">Zwölf Stockwerke. </ta><ta id="Seg_2594" s="T125" e="T126">Gott! </ta><ta id="Seg_2595" s="T126" e="T127">((atmet ein)) </ta><ta id="Seg_2596" s="T127" e="T128">Ich meine, er hätte jede Sekunde herunterfallen können. </ta><ta id="Seg_2597" s="T128" e="T129">((atmet ein)) </ta><ta id="Seg_2598" s="T129" e="T130">Es war bekloppt. </ta><ta id="Seg_2599" s="T130" e="T131">und äh </ta><ta id="Seg_2600" s="T131" e="T132">• • • </ta><ta id="Seg_2601" s="T132" e="T133">Weißt du (als) ((unv.)) </ta></annotation><annotation name="k" tierref="TIE6"><ta id="Seg_2602" s="T119" e="T120">[ði:]</ta></annotation></segmented-tier><segmented-tier id="TIE7" category="nn" type="d" display-name="[nn]"><segmentation name="Event" tierref="TIE7"><ats n="e" id="Seg_2603" s="T0" e="T1">((Transkriptionsbeginn nach 0,9s)) </ats></segmentation></segmented-tier></segmented-body><conversion-info><basic-transcription-conversion-info><conversion-timeline><conversion-tli id="T0"/><conversion-tli id="T1"/><conversion-tli id="T2"/><conversion-tli id="T